Wu Xing)|4=it|5=Metallo (elemento)|6=vi|7=Kim (Ngũ hành)|8=tr|9=Metal (klasik element)|10=uk|11=Метал (У-сін)|lt=Metal (金)|13=User:Immanuelle/Metal (wuxing)|ja|Metal (金)|1=Metal (wuxing)|lt=Metal (金)|2=es|3=Metal (Wu Xing)|4=it|5=Metallo (elemento)|6=vi|7=Kim (Ngũ hành)|8=tr|9=Metal (klasik element)|10=uk|11=Метал (У-сін)|lt=Metal (金)|qq=}}, and {{ill|water|zh|Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|1=Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|2=uk|3=Вода (У-сін)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|qq=|qq=draft|12=simple|13=User:Immanuelle/water|qq=|12=simple|13=User:Immanuelle/water|13=User:Immanuelle/Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|qq=|12=simple|13=User:Immanuelle/water|13=User:Immanuelle/Water (wuxing)|lt=Water (水)|comment=doing this to prevent wrong interwiki linking by bot|1=Water (wuxing)|2=uk|3=Вода (У-сін)|4=als|5=Wasser in dr chinesische Fümf-Elemänt-Leer|6=bcl|7=Tubig (wuxing)|8=vi|9=Thủy (Ngũ hành)|10=pt|11=Água (astrologia)|lt=Water (水)|qq=}}), the {{ill|ten heavenly stems|ja|十干|qq=|qq=draft|12=simple|13=User:Immanuelle/ten heavenly stems|qq=|12=simple|13=User:Immanuelle/ten heavenly stems|qq=|12=simple|13=User:Immanuelle/ten heavenly stems|qq=}}, the {{ill|twelve earthly branches|ja|十二支|qq=|qq=draft|12=simple|13=User:Immanuelle/twelve earthly branches|qq=|12=simple|13=User:Immanuelle/twelve earthly branches|qq=|12=simple|13=User:Immanuelle/twelve earthly branches|qq=}}, and the {{ill|eight trigrams|ja|八卦|qq=|qq=draft|12=simple|13=User:Immanuelle/eight trigrams|qq=|12=simple|13=User:Immanuelle/eight trigrams|qq=|12=simple|13=User:Immanuelle/eight trigrams|qq=}} of {{ill|I Ching|ja|易経|qq=|qq=draft|12=simple|13=User:Immanuelle/I Ching|qq=|12=simple|13=User:Immanuelle/I Ching|qq=|12=simple|13=User:Immanuelle/I Ching|qq=}}. When these numbers shift positions, interpretations are added to form the "Nine Stars."

According to legend, {{ill|Yu the Great|ja|禹|qq=|qq=draft|12=simple|13=User:Immanuelle/Yu the Great|qq=|12=simple|13=User:Immanuelle/Yu the Great|qq=|12=simple|13=User:Immanuelle/Yu the Great|qq=}}, founder of the {{ill|Xia Dynasty|ja|夏王朝|1=Xia dynasty|qq=|qq=draft|12=simple|13=User:Immanuelle/Xia Dynasty|13=User:Immanuelle/Xia dynasty|qq=|12=simple|13=User:Immanuelle/Xia Dynasty|13=User:Immanuelle/Xia dynasty|qq=|12=simple|13=User:Immanuelle/Xia Dynasty|13=User:Immanuelle/Xia dynasty|qq=}}, conceived this magic square when he encountered a sacred turtle emerging from the {{ill|Luo River|ja|洛水|qq=|qq=draft|12=simple|13=User:Immanuelle/Luo River|qq=|12=simple|13=User:Immanuelle/Luo River|qq=|12=simple|13=User:Immanuelle/Luo River|qq=}}. This magic square is called the "Writing of the Luo" ({{ill|Hetu and Luoshu|ja|洛書|qq=|qq=draft|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=}}), one of the {{ill|Hetu and Luoshu|ja|河図洛書|qq=|qq=draft|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=|12=simple|13=User:Immanuelle/Hetu and Luoshu|qq=}}.

== The Nine Stars ==
In Japanese {{ill|Onmyōdō|ja|陰陽道|qq=|qq=draft|12=simple|13=User:Immanuelle/Onmyōdō|qq=|12=simple|13=User:Immanuelle/Onmyōdō|qq=|12=simple|13=User:Immanuelle/Onmyōdō|qq=}}, the following table associates the Nine Stars with the {{ill|Wuxing (Chinese philosophy)|ja|五行思想|1=Wuxing (Chinese philosophy)|2=ja|3=五行思想|lt=Five Elements (Wuxing)|Wuxing (Chinese philosophy)=Wuxing (Chinese philosophy)|lt=five elements|qq=|qq=draft|12=simple|13=User:Immanuelle/Wuxing (Chinese philosophy)|13=User:Immanuelle/Wuxing (Chinese philosophy)|qq=|12=simple|13=User:Immanuelle/Wuxing (Chinese philosophy)|13=User:Immanuelle/Wuxing (Chinese philosophy)|qq=|12=simple|13=User:Immanuelle/Wuxing (Chinese philosophy)|13=User:Immanuelle/Wuxing (Chinese philosophy)|qq=}}, {{ill|directions|ja|方位|qq=|qq=draft|12=simple|13=User:Immanuelle/directions|qq=|12=simple|13=User:Immanuelle/directions|qq=|12=simple|13=User:Immanuelle/directions|qq=}}, {{ill|eight trigrams|ja|八卦|qq=|qq=draft|12=simple|13=User:Immanuelle/eight trigrams|qq=|12=simple|13=User:Immanuelle/eight trigrams|qq=|12=simple|13=User:Immanuelle/eight trigrams|qq=}}, and colors, forming the '''Nine Stars Chart''' used to predict {{ill|fortune|ja|運勢|qq=|qq=draft|12=simple|13=User:Immanuelle/fortune|qq=|12=simple|13=User:Immanuelle/fortune|qq=|12=simple|13=User:Immanuelle/fortune|qq=}} and the {{ill|auspiciousness|ja|吉凶|qq=|qq=draft|12=simple|13=User:Immanuelle/auspiciousness|qq=|12=simple|13=User:Immanuelle/auspiciousness|qq=|12=simple|13=User:Immanuelle/auspiciousness|qq=}} of directions based on a person's birth year.

